# shellcheck shell=bash
# Generated by `gash __compat generate` from bash_completion: do not edit. 2a5c317b
__gash_complete() {
    local cur="${COMP_WORDS[COMP_CWORD]}"
    local cmd="${COMP_WORDS[0]}"

    # A Gash alias (gsync, chri, flf...) completes like its function.
    local expansion
    if expansion="$(alias "$cmd" 2>/dev/null)"; then
        expansion="${expansion#*=\'}"
        cmd="${expansion%%[\' ]*}"
    fi

    case "$cmd" in
        # AI provider completion (first argument only)
        ai_ask | ai_query)
            if ((COMP_CWORD == 1)); then
                mapfile -t COMPREPLY < <(compgen -W "claude gemini" -- "$cur")
            else
                COMPREPLY=()
            fi
            ;;

        # AI sysinfo: provider + --raw + --no-color
        ai_sysinfo)
            mapfile -t COMPREPLY < <(compgen -W "claude gemini --raw --no-color" -- "$cur")
            ;;

        # File completion
        archive_extract | file_backup | git_dump_revisions)
            mapfile -t COMPREPLY < <(compgen -f -- "$cur")
            ;;

        # Upgrades with a plan and one question
        chrome_headless_update | node_upgrade)
            mapfile -t COMPREPLY < <(compgen -W "--yes --dry-run --help" -- "$cur")
            ;;

        # dirs_find_large: directories + flags
        dirs_find_large)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "--size --depth --limit --exclude --no-ignore --xdev --allow-root --with-mtime --json --null --human --no-human --no-color --help" -- "$cur")
            else
                mapfile -t COMPREPLY < <(compgen -d -- "$cur")
            fi
            ;;

        # dirs_largest: directories + flags
        dirs_largest)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "--limit --depth --min-size --exclude --no-ignore --xdev --allow-root --json --null --human --no-human --no-color --help" -- "$cur")
            else
                mapfile -t COMPREPLY < <(compgen -d -- "$cur")
            fi
            ;;

        # dirs_list_empty: directories + flags
        dirs_list_empty)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "--min-depth --depth --exclude --ignore-dotfiles --no-ignore --xdev --allow-root --null --count --json --help" -- "$cur")
            else
                mapfile -t COMPREPLY < <(compgen -d -- "$cur")
            fi
            ;;

        # disk_usage — just --no-color
        disk_usage)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "--no-color --help" -- "$cur")
            fi
            ;;

        # Docker compose check/upgrade/scan: dirs + flags (incl. --no-color)
        docker_compose_check)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "--json --no-color --help" -- "$cur")
            else
                mapfile -t COMPREPLY < <(compgen -d -- "$cur")
            fi
            ;;

        docker_compose_scan)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "-d --depth -j --json --no-color --help" -- "$cur")
            else
                mapfile -t COMPREPLY < <(compgen -d -- "$cur")
            fi
            ;;

        docker_compose_upgrade)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "--dry-run --force -f --yes -y --no-color --help" -- "$cur")
            else
                mapfile -t COMPREPLY < <(compgen -d -- "$cur")
            fi
            ;;

        docker_prune_all | git_apply_patch | git_repair)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "-y --yes --dry-run --help" -- "$cur")
            fi
            ;;

        docker_start_all | docker_stop_all)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "-y --yes --help" -- "$cur")
            fi
            ;;

        # files_largest: directories + flags
        files_largest)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "--limit --min-size --exclude --depth --no-ignore --xdev --follow-symlinks --allow-root --json --null --human --no-human --no-color --help" -- "$cur")
            else
                mapfile -t COMPREPLY < <(compgen -d -- "$cur")
            fi
            ;;

        # gash_doctor: --timing, --no-color
        gash_doctor)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "--timing --no-color --help" -- "$cur")
            fi
            ;;

        # Only --help as an option (words complete as files)
        gash_ssh_auto_unlock | history_grep | process_find | sudo_last | wsl_explorer | wsl_taskmanager)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "--help" -- "$cur")
            fi
            ;;

        # Git tag completion, with the confirmation flags
        git_add_tag | git_delete_tag)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "-y --yes --dry-run --help" -- "$cur")
            elif type -P git >/dev/null 2>&1 && git rev-parse --is-inside-work-tree >/dev/null 2>&1; then
                mapfile -t COMPREPLY < <(compgen -W "$(git tag -l 2>/dev/null)" -- "$cur")
            else
                COMPREPLY=()
            fi
            ;;

        # Git tag completion
        git_list_tags)
            if type -P git >/dev/null 2>&1 && git rev-parse --is-inside-work-tree >/dev/null 2>&1; then
                mapfile -t COMPREPLY < <(compgen -W "$(git tag -l 2>/dev/null)" -- "$cur")
            else
                COMPREPLY=()
            fi
            ;;

        git_sync)
            mapfile -t COMPREPLY < <(compgen -W "-m --message --no-push --dry-run -y --yes --help" -- "$cur")
            ;;

        # hgrep — its options
        hgrep)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "-n --limit -a --all -r --reverse -j --json -H --no-highlight -E --regex -c --count -g --group --pick --no-color --help" -- "$cur")
            fi
            ;;

        # ip_public — --no-color and --raw
        ip_public)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "--no-color --raw --help" -- "$cur")
            fi
            ;;

        # Directory completion (other)
        mkdir_cd)
            mapfile -t COMPREPLY < <(compgen -d -- "$cur")
            ;;

        path_add)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "--append --help" -- "$cur")
            else
                mapfile -t COMPREPLY < <(compgen -d -- "$cur")
            fi
            ;;

        # Kill functions — -y/--yes and the 2.0 -f/--force
        port_kill | process_kill)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "-y --yes -f --force --help" -- "$cur")
            fi
            ;;

        remote_exec)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "--script --help" -- "$cur")
            fi
            ;;

        remote_pull | remote_push)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "-r --recursive -p --preserve --no-progress --force --help" -- "$cur")
            fi
            ;;

        remote_sync_pull | remote_sync_push)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "--delete --dry-run --no-progress --force --exclude= --help" -- "$cur")
            fi
            ;;

        # services_stop — confirmation flags and --dry-run
        services_stop)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "-y --yes -f --force --dry-run --help" -- "$cur")
            fi
            ;;

        # System info sections + flags
        sysinfo)
            mapfile -t COMPREPLY < <(compgen -W "overview identity storage services auth network security webstack mail infra system all --llm --no-color --help" -- "$cur")
            ;;

        # tree_stats: directories + flags
        tree_stats)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "--depth --top --exclude --no-ignore --xdev --follow-symlinks --allow-root --json --no-color --help" -- "$cur")
            else
                mapfile -t COMPREPLY < <(compgen -d -- "$cur")
            fi
            ;;

        wsl_compact)
            mapfile -t COMPREPLY < <(compgen -W "--status -y --yes --help" -- "$cur")
            ;;

        # WSL stop functions — -y/--yes
        wsl_restart | wsl_shutdown)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "-y --yes --help" -- "$cur")
            fi
            ;;

        # The reference card topics, and the 3.x commands of the binary
        gash)
            if ((COMP_CWORD == 1)); then
                mapfile -t COMPREPLY < <(compgen -W "all files system nav git docker remote dev llm agent ai gash init update version hte logs wsl win" -- "$cur")
            else
                case "${COMP_WORDS[1]-}" in
                    init | update | version | hte)
                        local __gash_bin=""
                        if declare -F __gash_compat_ready >/dev/null && __gash_compat_ready; then
                            __gash_bin="$__GASH_BIN"
                        fi
                        if [[ -n "$__gash_bin" ]]; then
                            mapfile -t COMPREPLY < <("$__gash_bin" __complete "${COMP_WORDS[@]:1:COMP_CWORD}" 2>/dev/null | while IFS= read -r line; do
                                [[ "$line" == :* ]] && continue
                                printf '%s\n' "${line%%$'\t'*}"
                            done)
                        else
                            COMPREPLY=()
                        fi
                        ;;
                    *) COMPREPLY=() ;;
                esac
            fi
            ;;

        gash_help)
            if [[ "$cur" == -* ]]; then
                mapfile -t COMPREPLY < <(compgen -W "--list --search --short --bash --no-color" -- "$cur")
            elif [[ "${COMP_WORDS[1]-}" == "--search" ]] && ((COMP_CWORD == 2)); then
                # After --search, user types keyword freely
                COMPREPLY=()
            elif ((COMP_CWORD == 1)); then
                # Function names with registered help, and their aliases
                mapfile -t COMPREPLY < <(compgen -W "agent_replace ai_ask ask ai_query ai_sysinfo sysinfo_ai all_colors archive_extract axe chrome_headless_update chri dirs_find_large dfl dirs_largest dld dirs_list_empty dle disk_usage du2 docker_compose_check dcc docker_compose_scan dcscan docker_compose_upgrade dcup2 docker_prune_all dpa docker_start_all daa docker_stop_all dsa file_backup fbk files_largest flf gash gash_ai_list gash_db_list gash_db_test gash_doctor gdoctor gash_env_init gash_help gash_inspiring_quote gash_migrate gash_ssh_auto_unlock gash_uninstall gash_unload gash_upgrade gash_username git_add_tag gat git_apply_patch gpatch git_delete_tag gdt git_dump_revisions gdr git_list_tags glt git_repair gheal git_sync gsync hgrep history_grep hg ip_public myip llm_assert llm_config llm_count llm_db_explain llm_db_query llm_db_sample llm_db_schema llm_db_tables llm_deps llm_dns llm_docker_check llm_env llm_exec llm_find llm_git_diff llm_git_log llm_git_status llm_grep llm_hash llm_http llm_log llm_ports llm_procs llm_project llm_read llm_stat llm_tcp llm_textcheck llm_textstats llm_tls llm_tree mkdir_cd mkcd node_detect_version node_upgrade nvmc nvm_prune_versions nvmp path_add php_detect_version port_kill ptk process_find pf process_kill pk remote_exec rex remote_hosts rh remote_pull rpull remote_push rpush remote_sync_pull rspull remote_sync_push rspush services_stop svs sudo_last plz sysinfo si tree_stats tls wsl_compact wslc wsl_explorer wex wsl_restart wr wsl_shutdown wsd wsl_taskmanager wtm --list --search --short --bash --no-color" -- "$cur")
            else
                COMPREPLY=()
            fi
            ;;

        # Everything else: empty COMPREPLY lets -o default provide file completion
        *)
            COMPREPLY=()
            ;;
    esac
}
